export type ResourceScope = 'PLATFORM' | 'USER' | 'PROJECT';

/**
 * A Resource is pinned to scope, ownership, type, sourceModule, externalId, and version. Identity uniqueness is within PLATFORM or an individual USER or PROJECT namespace; identical source identities may coexist across namespaces without copying a Resource for association. These identity fields do not change for a Resource ID. displayMetadata is mutable, non-authoritative presentation; updates refresh updatedAt. myProjectCount is scoped to the current authenticated User and must never count another User's Projects or scope-mismatched associations. Scope is required in every Resource response; ownerUserId and ownerProjectId are not response fields.
 */
export type Resource = {
    id: PlatformId;
    type: ResourceType;
    scope: ResourceScope;
    sourceModule: string;
    /**
     * Opaque identifier assigned by the source module.
     */
    externalId: string;
    version: string;
    displayMetadata: ResourceDisplayMetadata;
    /**
     * Number of the current User's Projects with legal current associations to this Resource; excludes foreign Projects and scope-mismatched associations. For PROJECT, only its owner Project may count.
     */
    myProjectCount: number;
    createdAt: Timestamp;
    updatedAt: Timestamp;
};

/**
 * Stable public presentation subset; extra non-authoritative display keys may be present.
 */
export type ResourceDisplayMetadata = {
    name: string;
    description: string;
    tags: Array<string>;
    /**
     * Displayable technical field names and string values; an empty object is valid.
     */
    specifications: {
        [key: string]: string;
    };
    [key: string]: unknown;
};

/**
 * Immutable Action input binding and configuration record. Resource IDs identify saved bindings; Resource contents and execution environment are not frozen. Changing inputs or configuration creates a new Validation. EMBODEX_MODEL_IMPORT has empty inputs and exact receiptId config; no baseline defaults or receipt normalization beyond UUID lowercase. Canonical binding cannot be cloned. SIMCORE_EVALUATION requires empty inputs and the exact SimcoreEvaluationConfig; source provenance is verified server-side and omitted episodes becomes 5 before saving.
 */
export type Validation = ActionValidationBinding & {
    id: PlatformId;
    projectId: PlatformId;
    actionKey: ActionKey;
    inputs: ValidationInputs | EmbodexDesignInputs;
    configSnapshot: JsonObject;
    createdAt: Timestamp;
    updatedAt: Timestamp;
};

/**
 * Explicit Action and immutable Action-specific input/configuration bindings. Required fields, ActionKey and the exact production input/configuration shape are checked before Project ownership. The owned Project must support the Action. For SIMCORE_TRAINING, both Resources must first be visible under ResourceScope. Absent and invisible IDs produce the same 404 RESOURCE_NOT_FOUND without revealing which ID failed, before association or role checks. Both Resources must then have legal current associations with the Project and match their ROBOT and ALGORITHM roles. Input shape is determined by ActionDefinition, not duplicated as Action-specific branches in creation or dispatch core. Creation locks distinct normalized association rows until its transaction ends and atomically saves all bindings and configSnapshot. A later association removal does not change an existing Validation. Legacy robotResourceId and algorithmResourceId fields are rejected. EMBODEX_DESIGN requires empty inputs and strict design configuration, with no Resource checks. requirement is normalized with String.trim() before the immutable snapshot is saved; SIMCORE_TRAINING retains arbitrary historical configSnapshot objects. EMBODEX_MODEL_IMPORT has empty inputs and exact receiptId config; no baseline defaults or receipt normalization beyond UUID lowercase. Canonical binding cannot be cloned. SIMCORE_EVALUATION requires empty inputs and the exact SimcoreEvaluationConfig; source provenance is verified server-side and omitted episodes becomes 5 before saving. EMBODEX_PUBLISH_EXISTING requires empty inputs and exact threadId and confirmationId in configSnapshot; canonical binding is created exclusively through the dedicated publication flow and cannot be bypassed or duplicated. DEPLOYX_DEPLOY is a server-created canonical binding through POST project/deployx/deployments only. This schema describes its stored shape; public generic CreateValidation rejects DEPLOYX_DEPLOY with 409 ACTION_ENTRYPOINT_REQUIRED, even if shape-valid. Generic Task creation may only reuse its exact existing canonical Validation/Task; manual clones and new dispatch are rejected.
 */
export type CreateValidationRequest = ActionValidationBinding & {
    projectId: PlatformId;
    actionKey: ActionKey;
    inputs: ValidationInputs | EmbodexDesignInputs;
    configSnapshot: JsonObject;
};

/**
 * Named Resource input map for SIMCORE_TRAINING only. Exactly robot and algorithm are required, case-sensitive own JSON object keys. Each value is a Platform Resource UUID. Missing or unknown keys, null, arrays and non-UUID values return 400 INVALID_REQUEST before Project ownership. robot requires ROBOT and algorithm requires ALGORITHM; Resource type checks occur only after ownership, Action support, all visibility checks and all association checks. UUID letter case does not change Resource identity. Internal test Actions are not accepted by this schema.
 */
export type ValidationInputs = {
    robot: PlatformId;
    algorithm: PlatformId;
};

/**
 * Exactly an empty JSON object; no Resource bindings.
 */
export type EmbodexDesignInputs = {
    [key: string]: never;
};

/**
 * Embodex robot design configuration. Supports backward-compatible legacy SO-101 baseline requests (with buildMode=baseline) and v1.7 multi-template or general robot requests (templateId string or explicit null, without buildMode).
 */
export type EmbodexDesignConfig = {
    /**
     * JavaScript String.trim() result must contain 3 to 4000 Unicode code points; save and send that trimmed value. Pattern is evaluated with Unicode semantics; no raw UTF-16 length limit or silent truncation.
     */
    requirement: string;
    /**
     * Explicit SO-101 official baseline template identifier for legacy baseline mode.
     */
    templateId: 'so101_v1';
    /**
     * Explicit acknowledgment of legacy baseline construction; requirement does not alter model parameters.
     */
    buildMode: 'baseline';
} | {
    /**
     * JavaScript String.trim() result must contain 3 to 4000 Unicode code points; save and send that trimmed value. Pattern is evaluated with Unicode semantics; no raw UTF-16 length limit or silent truncation.
     */
    requirement: string;
    templateId: string | null;
};

/**
 * Strict canonical lowercase UUID representation matching ^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$.
 */
export type CanonicalUuid = string;

/**
 * Exactly an empty JSON object; no Resource inputs permitted for publishing an existing confirmed model.
 */
export type EmbodexPublishExistingInputs = {
    [key: string]: never;
};

/**
 * Configuration snapshot for EMBODEX_PUBLISH_EXISTING. Strictly contains threadId and confirmationId canonical UUIDs identifying the validated conversation turn and server-frozen model snapshot.
 */
export type EmbodexPublishExistingConfig = {
    threadId: CanonicalUuid;
    confirmationId: CanonicalUuid;
};

/**
 * Current confirmation state for the project thread; READY provides confirmation UUID, NOT_READY returns null.
 */
export type EmbodexConfirmationCurrentResponse = {
    status: 'READY';
    confirmationId: CanonicalUuid;
} | {
    status: 'NOT_READY';
    confirmationId: null;
};

/**
 * Client publication intent payload containing verified threadId and confirmationId only.
 */
export type CreateEmbodexPublicationRequest = {
    threadId: CanonicalUuid;
    confirmationId: CanonicalUuid;
};

/**
 * Accepted publication task identifier. Query task status endpoint for execution progress and result.
 */
export type CreateEmbodexPublicationResponse = {
    taskId: CanonicalUuid;
};

export type ActionValidationBinding = {
    actionKey: 'SIMCORE_TRAINING';
    inputs: ValidationInputs;
    configSnapshot: JsonObject;
} | {
    actionKey: 'EMBODEX_DESIGN';
    inputs: EmbodexDesignInputs;
    configSnapshot: EmbodexDesignConfig;
} | {
    actionKey: 'EMBODEX_MODEL_IMPORT';
    inputs: EmbodexDesignInputs;
    configSnapshot: EmbodexModelImportConfig;
} | {
    actionKey: 'EMBODEX_PUBLISH_EXISTING';
    inputs: EmbodexPublishExistingInputs;
    configSnapshot: EmbodexPublishExistingConfig;
} | EvaluationValidationBinding | {
    actionKey: 'DEPLOYX_DEPLOY';
    inputs: DeployxDeployInputs;
    configSnapshot: DeployxDeployConfig;
};

/**
 * Cancellation intent has been persisted and cancellation is awaiting external confirmation. CANCELED is reached only after the applicable external contract confirms cancellation. TIMEOUT is a platform wait or freshness outcome and does not prove external execution stopped.
 */
export type TaskStatus = 'PENDING' | 'QUEUED' | 'RUNNING' | 'CANCEL_REQUESTED' | 'SUCCEEDED' | 'FAILED' | 'CANCELED' | 'TIMEOUT';

/**
 * Explicit, case-sensitive business Action identity shared by Activity Action type, CreateValidationRequest actionKey, Validation actionKey, CreateTaskRequest actionKey and Task actionKey. Production v0.1 supports SIMCORE_TRAINING, EMBODEX_DESIGN and EMBODEX_MODEL_IMPORT, only in EMBODIED_AI Projects. No missing-value fallback, trimming or case normalization is applied. Internal execution routing is not public Action identity. Adding another production Action requires an approved Contract change. EMBODEX_MODEL_IMPORT is a local import of a verified server receipt, not a CAD execution; supported only in EMBODIED_AI. It is not advertised as an independent Activity. SIMCORE_EVALUATION evaluates a verified final policy in its original template, only in EMBODIED_AI Projects. EMBODEX_PUBLISH_EXISTING publishes an existing verified model snapshot without re-running CAD, supported only in EMBODIED_AI Projects.
 */
export type ActionKey = 'SIMCORE_TRAINING' | 'EMBODEX_DESIGN' | 'EMBODEX_MODEL_IMPORT' | 'SIMCORE_EVALUATION' | 'EMBODEX_PUBLISH_EXISTING' | 'DEPLOYX_DEPLOY';

/**
 * Public Task snapshot. actionKey is the immutable business identity saved when the Task is created and is required in create, detail and list responses, including migrated historical terminal Tasks. Reads do not require a current new-task execution mapping or a nonempty legacy route. DEPLOYX_DEPLOY uses the same Task envelope and immutable canonical validationId. Adopted upstream retries have external_job_id and submission_attempted_at set atomically before visibility, so are polled and never created upstream again. When a verified RECOVER response identifies a distinct new/reused DEPLOY, atomically adopt it and close the original still-active platform Task as FAILED with exactly one immutable Result. Preserve original upstream SAFETY_BLOCKED history. Merely accepting a recovery STOP does not close the suspended Task or prove safety.
 */
export type Task = {
    id: PlatformId;
    projectId: PlatformId;
    validationId: PlatformId;
    actionKey: ActionKey;
    status: TaskStatus;
    idempotencyKey: string;
    createdAt: Timestamp;
    updatedAt: Timestamp;
};

/**
 * Explicit Action creation request. actionKey is required and uses the same identity as Activity Action type and the saved Validation actionKey. Inputs and configSnapshot come from that immutable Validation; Task creation does not accept inline inputs or internal routing fields. See createTask for ownership, Action support, Validation relationship, Action consistency, idempotency and new-task configuration failure precedence.
 */
export type CreateTaskRequest = {
    projectId: PlatformId;
    validationId: PlatformId;
    actionKey: ActionKey;
};

/**
 * A persisted Result. producedResources contains only platform-materialized Resource references, separate from module-specific data. Historical Results and Results without produced Resources return an empty array, never an omitted or null field. List and detail responses use the same representation. DEPLOYX_DEPLOY keeps this Result envelope; sourceModule=deployx and data conforms to DeployxResultData, internal result_kind=deployx-final. One immutable final result per Task; later safety observations are kept on deployment GET, never overwrite Result.
 */
export type Result = unknown & {
    id: PlatformId;
    taskId: PlatformId;
    sourceModule: string;
    summary: string;
    data: JsonObject;
    /**
     * Stable ascending outputKey order, with unique outputKey values within this Result. Keys identify output roles within the Result and are not restricted to a production Action or module enum. Each reference identifies a Resource atomically materialized with this Result; it contains no Artifact, payload, provider or raw external reference. Removing a Project Resource association does not remove these historical references or grant Artifact access.
     */
    producedResources: Array<ProducedResourceRef>;
    createdAt: Timestamp;
    updatedAt: Timestamp;
};

export type ProducedResourceRef = {
    /**
     * Normalized output role key after JavaScript String.trim(), nonempty and at most 64 Unicode code points, with no surrounding whitespace. Internal whitespace is allowed. Uniqueness and ascending order use these normalized values.
     */
    outputKey: string;
    resourceId: PlatformId;
};

